from pathlib import Path
import re

P=Path("index.html")
s=P.read_text(encoding="utf-8")

# Turn the existing card collection into a social-feed presentation without
# duplicating the canonical content already generated by app.py.
s=s.replace('<main class="main" id="explore">','<main class="main" id="explore"><div class="feed-shell">',1)
s=s.replace('</main>\n<footer','</div></main>\n<footer',1)

css=r'''
<style id="npcbook-feed-upgrade">
:root{--feed-max:1180px;--feed-col:620px;--x-bg:#000;--x-panel:#000;--x-border:#202833;--x-text:#e7e9ea;--x-muted:#71767b;--x-blue:#1d9bf0}
body{background:var(--x-bg)!important;color:var(--x-text)!important}
.topbar{background:#000e!important;border-bottom:1px solid var(--x-border)!important}
.nav{max-width:var(--feed-max)!important}
.hero,.stats{display:none!important}
.main{max-width:var(--feed-max)!important;margin:auto!important;padding:0!important;display:grid!important;grid-template-columns:220px minmax(0,var(--feed-col)) 300px!important;gap:22px!important}
.main:before{content:"NPCBOOK · BLSSNVJ21\A\A⌂  Home\A👤  NPCs\A🌍  Worlds\A⚔  Quests\A📜  Lore\A🔥  Trending\A⚙  Settings";white-space:pre;position:sticky;top:70px;height:fit-content;padding:20px 12px;color:#e7e9ea;font-weight:800;line-height:2.45;border-right:1px solid var(--x-border)}
.feed-shell{min-width:0;border-left:1px solid var(--x-border);border-right:1px solid var(--x-border)}
.main:after{content:"TRENDING\A\A#PigeonCouncil\AThe pigeons know too much.\A\A#BLSSNVJ21\AThe signal is still blinking.\A\A#IronLegion\AThe lava road remains lava.";white-space:pre-wrap;position:sticky;top:70px;height:fit-content;margin-top:20px;padding:18px;background:#0a0a0a;border:1px solid var(--x-border);border-radius:18px;color:#9ca3af;line-height:1.55}
.toolbar{position:sticky!important;top:58px!important;z-index:20;background:#000e!important;backdrop-filter:blur(14px);margin:0!important;padding:13px 16px!important;border-bottom:1px solid var(--x-border)}
.filters{display:none!important}.result-count{margin-left:auto;color:var(--x-muted)!important}
.feed-banner{display:flex;justify-content:space-between;gap:10px;padding:15px 18px;border-bottom:1px solid var(--x-border);font-weight:900;font-size:20px}.feed-banner small{font-size:12px;color:var(--x-muted);font-weight:500}
.composer{background:#000!important;border-bottom:1px solid var(--x-border)!important;padding:16px 18px!important}
.grid{display:block!important}.card{background:#000!important;border:0!important;border-bottom:1px solid var(--x-border)!important;border-radius:0!important;padding:16px 18px!important;min-height:0!important}
.card:hover{background:#050505!important;transform:none!important;box-shadow:none!important}
.card h3{font-size:18px!important;margin:8px 0 6px!important;font-weight:800}.card p{font-size:15px!important;color:#d9d9d9!important;line-height:1.5}
.card-top:before{display:none}
.card .icon-btn{background:transparent!important;border:0!important;color:var(--x-muted)!important}.card-actions{margin-top:12px!important;display:flex!important;justify-content:space-between!important;gap:8px!important}.card-actions .btn{border:0!important;background:transparent!important;color:var(--x-muted)!important;padding:4px 8px!important;min-width:72px!important;text-align:left!important}.card-actions .btn:hover{color:var(--x-blue)!important}.x-stat{font-size:12px;color:var(--x-muted);margin-left:4px}.reply-box{display:none;margin-top:10px}.reply-box.show{display:block}.reply-box textarea{width:100%;min-height:60px;background:#000;border:1px solid var(--x-border);border-radius:12px;color:var(--x-text);padding:10px;resize:vertical}.reply-box button{margin-top:6px;border:0;border-radius:999px;padding:7px 14px;font-weight:800}
.card-actions .btn:hover{color:var(--x-blue)!important}
.empty{border:0!important}
@media(max-width:980px){.main{grid-template-columns:72px minmax(0,var(--feed-col))!important;max-width:700px!important}.main:before{content:"⌂\A👤\A🌍\A⚔\A📜\A🔥\A⚙";font-size:22px;text-align:center;line-height:3.05;padding:18px 5px}.main:after{display:none!important}}
@media(max-width:650px){.main{display:block!important;width:100%!important}.main:before,.main:after{display:none!important}.feed-shell{border:0!important}.toolbar{top:96px!important}.card{padding:15px 14px!important}.composer{padding:13px 14px!important}}
</style>
'''
s=s.replace('<style id="npcbook-feed-vnext">.feed-banner{align-items:center}.feed-tabs{display:flex;gap:18px;min-width:0}.feed-tab{border:0;background:transparent;color:#71767b;font:inherit;font-size:15px;font-weight:800;padding:3px 0;cursor:pointer;position:relative}.feed-tab.active{color:#e7e9ea}.feed-tab.active:after{content:"";position:absolute;left:0;right:0;bottom:-10px;height:3px;border-radius:3px;background:#1d9bf0}.local-post{position:relative}.local-post .eyebrow{color:#1d9bf0}@media(max-width:650px){.feed-banner{padding:14px!important;overflow:auto}.feed-tabs{gap:16px}.feed-banner small{display:none}}</head>',css+'</head>',1)

js=r'''
<script id="npcbook-feed-engine">
(()=>{window.addEventListener("error",e=>{if(e.error)console.error("NPCBook runtime error:",e.error);});window.addEventListener("unhandledrejection",e=>{console.error("NPCBook promise error:",e.reason);});const K="npcbook-feed-v15",grid=document.getElementById("resultsGrid"),search=document.getElementById("search"),cards=[...document.querySelectorAll(".card")];if(!grid||!cards.length)return;
const read=k=>{try{return JSON.parse(localStorage.getItem(K+"-"+k)||"null")}catch(_){return null}},write=(k,v)=>localStorage.setItem(K+"-"+k,JSON.stringify(v));
let seen=new Set(read("seen")||[]),filter=read("filter")||"all",query=read("query")||"",mode=read("mode")||"for-you";
const id=c=>{try{return JSON.parse(c.dataset.item).id}catch(_){return c.dataset.item}};
const shuffle=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function toast(m){let t=document.getElementById("feedToast");if(!t){t=document.createElement("div");t.id="feedToast";t.style.cssText="position:fixed;left:50%;bottom:22px;transform:translateX(-50%);z-index:999;background:#e7e9ea;color:#050505;padding:10px 16px;border-radius:999px;font-weight:800;box-shadow:0 10px 30px #0008";document.body.appendChild(t)}t.textContent=m;t.style.opacity="1";clearTimeout(t._x);t._x=setTimeout(()=>t.style.opacity="0",1800)}
function banner(){if(document.querySelector(".feed-banner"))return;let b=document.createElement("div");b.className="feed-banner";b.innerHTML='<div class="feed-tabs"><button class="feed-tab active" data-mode="for-you">For you</button><button class="feed-tab" data-mode="latest">Latest</button><button class="feed-tab" data-mode="saved">Saved</button></div><small>BLSSNVJ21 · text only · no repeats</small>';grid.parentNode.insertBefore(b,grid);b.querySelectorAll(".feed-tab").forEach(x=>x.onclick=()=>{b.querySelectorAll(".feed-tab").forEach(t=>t.classList.remove("active"));x.classList.add("active");mode=x.dataset.mode;seen=new Set();render()})}
function composer(){if(document.getElementById("localComposer"))return;let b=document.createElement("section");b.id="localComposer";b.className="composer";b.innerHTML='<div class="avatar">🤖</div><div class="composebox"><textarea maxlength="280" placeholder="What is happening in the omniverse?"></textarea><div class="compose-actions"><small><span>0</span>/280 · saved locally</small><button class="btn primary">Post</button></div></div>';grid.parentNode.insertBefore(b,grid);let ta=b.querySelector("textarea"),n=b.querySelector("small span"),draft=localStorage.getItem(K+"-draft")||"";ta.value=draft;n.textContent=draft.length;ta.oninput=()=>{n.textContent=ta.value.length;localStorage.setItem(K+"-draft",ta.value)};b.querySelector("button").onclick=()=>{let v=ta.value.trim();if(!v)return toast("The void requires words.");let p=read("posts")||[];p.unshift({id:"local-"+Date.now(),text:v,time:new Date().toISOString()});write("posts",p.slice(0,50));ta.value="";localStorage.removeItem(K+"-draft");toast("Broadcast stored locally. The pigeons approve.")}}
function localPosts(){return read("posts")||[]}function localCard(p){let c=document.createElement("article");c.className="card local-post";c.dataset.local="1";c.innerHTML='<div class="card-top"><span class="eyebrow">LOCAL · BLSSNVJ21</span><button class="icon-btn" type="button" aria-label="Delete post">Delete</button></div><h3>Anonymous NPC</h3><p></p><div class="meta"><span>just now</span><span>stored on this device</span></div><div class="card-actions"><button class="btn small ghost" type="button">Like</button></div>';c.querySelector("p").textContent=p.text;c.querySelector(".icon-btn").onclick=()=>{write("posts",localPosts().filter(x=>x.id!==p.id));c.remove();toast("Post deleted locally.")};c.querySelector(".btn").onclick=()=>{let likes=read("likes")||{};likes[p.id]=(likes[p.id]||0)+1;write("likes",likes);toast(likes[p.id]+" likes")};return c}
function enhanceCard(c){if(c.dataset.enhanced)return;c.dataset.enhanced="1";let actions=c.querySelector(".card-actions");if(!actions)return;actions.innerHTML='<button class="btn x-reply" type="button">Reply <span class="x-stat">0</span></button><button class="btn x-repost" type="button">Repost <span class="x-stat">0</span></button><button class="btn x-like" type="button">Like <span class="x-stat">0</span></button><button class="btn x-share" type="button">Share</button>';let box=document.createElement("div");box.className="reply-box";box.innerHTML='<textarea maxlength="280" placeholder="Post your reply"></textarea><button type="button">Reply</button>';actions.after(box);let key=()=>c.dataset.local==="1"?"local-"+(c.querySelector("p")?.textContent||"").slice(0,80):id(c),readStats=()=>{let all=read("stats")||{};return all[key()]||{reply:0,repost:0,like:0}},save=v=>{let all=read("stats")||{};all[key()]=v;write("stats",all)},update=()=>{let v=readStats();["reply","repost","like"].forEach(x=>{let n=c.querySelector(".x-"+x+" .x-stat");if(n)n.textContent=v[x]||0})};c.querySelector(".x-reply").onclick=()=>box.classList.toggle("show");c.querySelector(".x-repost").onclick=()=>{let v=readStats();v.repost++;save(v);update();toast("Reposted locally.")};c.querySelector(".x-like").onclick=()=>{let v=readStats();v.like++;save(v);update();toast("Liked locally.")};c.querySelector(".x-share").onclick=async()=>{let i;try{i=JSON.parse(c.dataset.item)}catch(_){i={name:"Anonymous NPC"}};try{await navigator.clipboard.writeText((i.name||"Anonymous NPC")+" — NPCBook");toast("Post text copied.")}catch(_){toast("Copy unavailable.")}};box.querySelector("button").onclick=()=>{let ta=box.querySelector("textarea");if(!ta.value.trim())return toast("Write something first.");let v=readStats();v.reply++;save(v);update();ta.value="";box.classList.remove("show");toast("Reply stored locally.")};update()}function render(){let matches=cards.filter(c=>(filter==="all"||c.dataset.type===filter)&&(!query||c.dataset.search.toLowerCase().includes(query)));let fresh;if(mode==="latest"){fresh=matches.slice();}else if(mode==="saved"){let likes=read("likes")||{};fresh=matches.filter(c=>likes[id(c)]);if(!fresh.length)toast("No saved posts yet. Double-click a post to save your chaos.");}else{fresh=matches.filter(c=>!seen.has(id(c)));if(!fresh.length){seen=new Set();fresh=matches.slice();if(fresh.length)toast("Feed exhausted. New chaos cycle unlocked.");}fresh=shuffle(fresh.slice());}grid.innerHTML="";if(mode!=="saved")localPosts().filter(p=>!query||p.text.toLowerCase().includes(query)).slice(0,20).forEach(p=>{let c=localCard(p);grid.appendChild(c);enhanceCard(c)});fresh.forEach(c=>{grid.appendChild(c);enhanceCard(c);if(mode==="for-you")seen.add(id(c))});write("seen",[...seen]);write("filter",filter);write("query",query);write("mode",mode);let rc=document.getElementById("resultCount");if(rc)rc.textContent=(fresh.length+(mode!=="saved"?localPosts().length:0))+" posts";let empty=document.getElementById("empty");if(empty)empty.classList.toggle("show",!fresh.length&&!localPosts().length)}
window.setFilter=f=>{filter=f;render()};search.addEventListener("input",e=>{query=e.target.value.trim().toLowerCase();seen=new Set();render()});
document.addEventListener("keydown",e=>{if(e.key==="/"&&document.activeElement!==search){e.preventDefault();search.focus()}});
cards.forEach(c=>c.addEventListener("dblclick",()=>{let i=JSON.parse(c.dataset.item),likes=read("likes")||{};likes[i.id]=(likes[i.id]||0)+1;write("likes",likes);toast(likes[i.id]+" likes for "+i.name)}));
banner();composer();search.value=query;render();
window.NPCBookFeed={reset:()=>{seen=new Set();localStorage.removeItem(K+"-seen");render();toast("Timeline reset. History vaporized.")},clear:()=>{Object.keys(localStorage).filter(k=>k.startsWith(K)).forEach(k=>localStorage.removeItem(k));location.reload()}};
})();
</script>
'''
s=s.replace('</body>',js+'</body>',1)
P.write_text(s,encoding="utf-8")
print("feed upgrade applied")
